import{_ as t,o as a,c as s,ak as o}from"./chunks/framework.sV-XtlWr.js";const u=JSON.parse(`{"title":"Code reach","description":"Which tests execute each application source file, recorded from Chromium's JavaScript coverage on a scheduled run and used by test selection, change coverage and preflight.","frontmatter":{"title":"Code reach","description":"Which tests execute each application source file, recorded from Chromium's JavaScript coverage on a scheduled run and used by test selection, change coverage and preflight.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/code-reach.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/code-reach.html"}],["meta",{"property":"og:title","content":"Code reach | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Which tests execute each application source file, recorded from Chromium's JavaScript coverage on a scheduled run and used by test selection, change coverage and preflight."}]]},"headers":[],"relativePath":"features/code-reach.md","filePath":"features/code-reach.md","lastUpdated":1790776547000}`),r={name:"features/code-reach.md"};function i(n,e,d,h,c,l){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="code-reach" tabindex="-1">Code reach <a class="header-anchor" href="#code-reach" aria-label="Permalink to &quot;Code reach&quot;">​</a></h1><p>&quot;Which tests reach this file?&quot; has an answer for test code from the locators a test calls. Code reach answers it for application code: an opt-in capture records the source files whose functions ran during each test, so a change to a component or a module maps to the tests that execute it.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>Set <code>captureCodeReach: true</code> in the reporter options, or <code>PIWI_CAPTURE_CODE_REACH=true</code>, with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in place. Coverage slows the page&#39;s JavaScript and reach changes slowly, so turn it on in one scheduled job, a nightly run, rather than on every run. A run without it keeps the reach the last one recorded.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// playwright.config.ts, in the nightly job</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { captureCodeReach: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NIGHTLY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }]],</span></span></code></pre></div><h2 id="what-it-records" tabindex="-1">What it records <a class="header-anchor" href="#what-it-records" aria-label="Permalink to &quot;What it records&quot;">​</a></h2><p>The fixtures start Chromium&#39;s JavaScript coverage on the test&#39;s first page and, at teardown, turn each script into source files:</p><ul><li>a module a dev server serves by path (Vite&#39;s <code>/src/components/Pay.vue</code>, <code>/@fs/…</code>) is the file itself;</li><li>a bundle is read through its source map, inline or fetched once per worker (20 MB and 5 seconds at most).</li></ul><p>A file counts when one of its functions ran. A module&#39;s top-level code runs as soon as it is imported, so it does not count: otherwise every eagerly loaded file would be reached by every test. Paths are relative to the repository root; files under <code>node_modules</code> or outside the repository are dropped, and at most 2,000 files are kept per test. Only the paths leave the machine, never code, counts or line numbers.</p><p>Paths resolve against the Playwright config&#39;s directory, then the repository root. Set <code>codeReachRoots</code> to the dev server&#39;s root when it is elsewhere; for Nuxt that is <code>app/</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { captureCodeReach: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, codeReachRoots: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;app&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }]],</span></span></code></pre></div><p>Code a bundler or dev server adds (module wrappers, preload helpers, hot-reload hooks) maps to no source of its own and counts for no file.</p><p>When the backend is instrumented (the <a href="/guide/backend-logs.html">Nitro or ASP.NET Core packages</a>), the handler file of each route a test called also counts as reached, with no capture of its own.</p><h2 id="supported-builds" tabindex="-1">Supported builds <a class="header-anchor" href="#supported-builds" aria-label="Permalink to &quot;Supported builds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Build</th><th>Source maps</th></tr></thead><tbody><tr><td>Vite dev server, Nuxt dev included</td><td>none needed: modules are served by path</td></tr><tr><td>Vite build</td><td><code>build: { sourcemap: true }</code></td></tr><tr><td>Next.js dev, Turbopack or webpack</td><td>on by default</td></tr><tr><td>Next.js build, Turbopack or webpack</td><td><code>productionBrowserSourceMaps: true</code></td></tr><tr><td>webpack build</td><td><code>devtool: &#39;source-map&#39;</code></td></tr></tbody></table><p>The map must be linked from the bundle: <code>sourcemap: &#39;hidden&#39;</code> and webpack&#39;s <code>hidden-source-map</code> write the map but not the comment that names it, so they record nothing.</p><p>Each was checked on a React app with four components, a lazy-loaded one, a shared utility and a module imported on start but never called, with Vite 8, webpack 5.111 and Next.js 16.3: every test recorded exactly the files it ran, none missed and none extra. Nuxt dev was checked on Piwi&#39;s own suite. The same builds without source maps record nothing.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>Chromium&#39;s block coverage slows the page&#39;s JavaScript, so the option stays off by default. Measured on a 4-core sandbox with headless Chromium:</p><ul><li><strong>A light page</strong> (the reporter&#39;s capture benchmark, <code>npm run reporter:bench</code>, 12 tests of 20 actions and assertions): 122 ms more per test on top of the default capture, 887 ms to 1,009 ms (median over three rounds).</li><li><strong>A script-heavy app</strong> (40 tests of Piwi&#39;s own suite against its Nuxt dev server, about 940 scripts per page, run alternately with the option off and on): 1.8 seconds more per test on average, a median test going from 10.1 to 12.3 seconds, about 20% more for the run.</li></ul><p>The extra time is spent in the browser, and it grows with the amount of JavaScript the page runs.</p><h2 id="where-it-is-used" tabindex="-1">Where it is used <a class="header-anchor" href="#where-it-is-used" aria-label="Permalink to &quot;Where it is used&quot;">​</a></h2><ul><li><strong><a href="./test-selection.html#impact-from-diff">Impact-from-diff</a></strong> maps a changed file to the tests that executed it. Code reach only adds tests: a changed source file that no test reached still widens the run to the whole suite, since code reach does not see module top-level code, server code or type-only modules.</li><li><strong><a href="./uncovered-changes.html">Uncovered changes</a></strong> counts a changed file as reached when a test executed it.</li><li><strong><a href="./preflight.html">Locator preflight</a></strong> calls a break <em>likely</em> only when one of its tests reaches the changed file.</li></ul><p>The dashboard&#39;s API serves the tests reaching one file and the whole map of a branch; see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a> (<code>/docs</code> on your instance).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Chromium only.</strong> Other browsers have no JavaScript coverage and record nothing.</li><li><strong>Observed reach, not coverage.</strong> A reached file may hide an untested branch: the unit is the file, never the line.</li><li>A build with neither per-module URLs nor source maps yields nothing, and so does code rendered on the server only, React server components included.</li><li>A module whose top-level code calls its own functions, a table built on import, counts for every test that loads it.</li><li>A function a minifier inlines into another as plain statements counts for the file it was inlined into.</li><li>Reach is per branch: a branch&#39;s own runs replace its tests&#39; reach, and the default branch&#39;s stands in for the rest.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/capture-fixtures.html">Capture fixtures</a>: what else the fixtures record</li><li><a href="./test-selection.html">Test selection</a>: impact-from-diff</li><li><a href="/guide/privacy.html">Privacy &amp; data flow</a>: what the reporter sends</li></ul>`,28)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
